def gen(rng):
    def fmt(ms):
        return str(len(ms)) + '\n' + '\n'.join(f'{s} {e}' for s, e in ms)
    tests = [fmt([(0, 1)]), fmt([(1, 2), (2, 3)]), fmt([(1, 5), (1, 5), (1, 5)]), fmt([(0, 10**9)]), fmt([(0, 5), (5, 10), (10, 15), (0, 15)]), fmt([(1, 3), (2, 4), (3, 6), (5, 7), (6, 9), (8, 10)])]
    for n in (2, 3, 5, 8, 10, 12):
        for _ in range(3):
            ms = []
            for _ in range(n):
                s = rng.randint(0, 20)
                ms.append((s, s + rng.randint(1, 8)))
            tests.append(fmt(ms))
    N = 100000
    ms = []
    for _ in range(N):
        s = rng.randint(0, 10**9 - 1)
        ms.append((s, min(10**9, s + rng.randint(1, 20000))))
    tests.append(fmt(ms))
    ms = []
    for _ in range(N):
        s = rng.randint(0, 1000)
        ms.append((s, s + rng.randint(1, 30)))
    tests.append(fmt(ms))
    tests.append(fmt([(i, i + 1) for i in range(N)]))
    tests.append(fmt([(0, 10**9 - i) for i in range(N)]))
    ms = []
    for _ in range(N):
        s = rng.randint(0, 10**9 - 1)
        ms.append((s, rng.randint(s + 1, 10**9)))
    tests.append(fmt(ms))
    return tests
